let report;const $=s=>document.querySelector(s),n=(v,d=0)=>new Intl.NumberFormat('ar-SA',{minimumFractionDigits:d,maximumFractionDigits:d}).format(v),pct=v=>n(v,2)+'٪',esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const set=(id,h)=>{const e=$('#'+id);if(e)e.innerHTML=h};
function sum(rows){const t={};for(const k of ['schools','primary','middle','secondary','teachers','teachersPresent','teachersAbsent','students','studentsPresent','lessons','supervisionVisits'])t[k]=rows.reduce((a,r)=>a+r[k],0);t.teacherRate=t.teachers?t.teachersPresent/t.teachers*100:0;t.studentRate=t.students?t.studentsPresent/t.students*100:0;return t}
function chart(rows){const W=1100,H=530,L=65,R=35,T=45,B=410,pw=W-L-R;let s=`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="نسب حضور المعلمين والمعلمات والطلبة حسب القطاع والفئة">`;for(let v=0;v<=100;v+=20){const y=B-v/100*(B-T);s+=`<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="#deeaee" stroke-width="1"/><text x="${L-13}" y="${y+6}" text-anchor="end" fill="#708995" font-size="18">${n(v)}٪</text>`}const step=pw/Math.max(rows.length,1);rows.forEach((r,i)=>{const cx=W-R-step*(i+.5);[['teacherRate','#00b2a3',7],['studentRate','#259ce2',-48]].forEach(([k,col,off])=>{const bh=r[k]/100*(B-T),x=cx+off;s+=`<rect x="${x}" y="${B-bh}" width="41" height="${bh}" rx="5" fill="${col}"/><text x="${x+20.5}" y="${B-bh-12}" text-anchor="middle" font-size="17" font-weight="700" fill="${col}">${pct(r[k])}</text>`});s+=`<text x="${cx}" y="450" text-anchor="middle" fill="#15445a" font-size="24" font-weight="700">${esc(r.sector)}</text><text x="${cx}" y="483" text-anchor="middle" fill="#718a96" font-size="20">${esc(r.category)}</text>`});return s+'</svg>'}
function card(sector,cat){const e=report.evidence.find(e=>e.sector===sector&&e.category===cat);if(!e)return '';const pics=(e.images||[]).map((im,i)=>`<a class="square-evidence-code image-code" href="${esc(im.path)}" target="_blank" rel="noopener"><img src="/madrasati/assets/qr/image-${e.id}-${i+1}.svg" alt="كود صورة الشاهد ${n(i+1)}"><span>فتح الصورة ${n(i+1)}</span></a>`).join('');return `<article class="evidence-card"><div class="evidence-title"><h3>${cat}</h3></div><div class="square-codes"><a class="square-evidence-code folder-code" href="${esc(e.url)}" target="_blank" rel="noopener"><img src="/madrasati/assets/qr/folder-${e.id}.svg" alt="كود شواهد ${esc(sector+' '+cat)}"><span>فتح ملف الشواهد</span></a>${pics}</div></article>`}
function render(){const sf=$('#sector-filter')?.value||'all',cf=$('#category-filter')?.value||'all',rows=report.records.filter(r=>(sf==='all'||r.sector===sf)&&(cf==='all'||r.category===cf)),t=sum(rows);set('kpis',[[t.schools,'عدد المدارس المتابَعة'],[t.lessons,'عدد الحصص المنفذة'],[t.supervisionVisits,'عدد الحضور الإشرافي']].map(([v,l])=>`<div class="stat"><b>${n(v)}</b><span>${l}</span></div>`).join(''));set('attendance-summary',[['teachers','المعلمين والمعلمات','teachersPresent','teacherRate'],['students','الطلبة','studentsPresent','studentRate']].map(([k,l,p,r])=>`<article class="attendance-card ${k}"><div><h3>نسبة حضور ${l} (٪)</h3><p>${n(t[p])} من ${n(t[k])}</p></div><strong>${pct(t[r])}</strong></article>`).join(''));set('professional-chart',chart(rows));set('sector-table',rows.map(r=>`<tr><td>${esc(r.sector+' – '+r.category)}</td>${['schools','primary','middle','secondary','lessons','supervisionVisits'].map(k=>`<td>${n(r[k])}</td>`).join('')}</tr>`).join('')+`<tr class="total"><td>الإجمالي</td>${['schools','primary','middle','secondary','lessons','supervisionVisits'].map(k=>`<td>${n(t[k])}</td>`).join('')}</tr>`);for(const kind of ['teachers','students']){const pre=kind+'Present',rate=kind==='teachers'?'teacherRate':'studentRate',cols=[kind,pre,...(kind==='teachers'?['teachersAbsent']:[])];set(kind+'-table',rows.map(r=>`<tr><td>${esc(r.sector+' – '+r.category)}</td>${cols.map(k=>`<td>${n(r[k])}</td>`).join('')}<td>${pct(r[rate])}</td></tr>`).join('')+`<tr class="total"><td>الإجمالي</td>${cols.map(k=>`<td>${n(t[k])}</td>`).join('')}<td>${pct(t[rate])}</td></tr>`)}set('head-reports-files',(report.headReports||[]).filter(h=>(sf==='all'||h.sector===sf)&&(cf==='all'||h.category===cf)).map(h=>`<article class="head-report-card"><div><h3>${esc(h.title)}</h3><a class="head-open" href="${esc(h.path)}" target="_blank" rel="noopener">فتح التقرير ↗</a>${h.originalPath?`<a class="head-original" href="${esc(h.originalPath)}" download>الملف الأصلي</a>`:''}</div><a class="head-qr" href="${esc(h.path)}" target="_blank" rel="noopener"><img src="/madrasati/assets/qr/head-${h.id}.svg" alt="كود ${esc(h.title)}"></a></article>`).join(''));set('evidence-grid',['الشمال','الجنوب','الوسط','رابغ'].filter(s=>sf==='all'||s===sf).map(s=>`<section class="sector-evidence-group"><h2>شواهد قطاع ${s}</h2><div class="sex-grid">${['بنين','بنات'].filter(c=>cf==='all'||c===cf).map(c=>card(s,c)).join('')}</div></section>`).join(''));document.querySelectorAll('.photo-button').forEach(b=>b.addEventListener('click',()=>{$('#lightbox-image').src=b.dataset.path;$('#lightbox-image').alt=b.getAttribute('aria-label');$('#lightbox-original').href=b.dataset.path;$('#lightbox-source').href=b.dataset.source;$('#lightbox').showModal()}))}
const embeddedReport=$('#report-data');if(embeddedReport){report=JSON.parse(embeddedReport.textContent);render()}else{fetch('/madrasati/data.json').then(r=>r.json()).then(d=>{report=d;render()})}for(const id of ['sector-filter','category-filter'])$('#'+id)?.addEventListener('change',()=>report&&render());$('#reset')?.addEventListener('click',()=>{$('#sector-filter').value='all';$('#category-filter').value='all';render()});$('#close-lightbox')?.addEventListener('click',()=>$('#lightbox').close());$('#lightbox')?.addEventListener('click',e=>{if(e.target===$('#lightbox'))$('#lightbox').close()});
